package br.com.catalogo;

import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.net.URI;
import java.util.*;
import java.util.List;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;

/** Cloud actions are explicit and scoped to the open SQLite profile. */
final class CloudDialog extends JDialog {
 final CloudSync sync;final Runnable changed;SwingWorker<?,?> worker;
 final JLabel account=new JLabel(),message=new JLabel("Conecte uma conta para sincronizar os metadados deste perfil.");
 final JLabel code=new JLabel(" ");final JTextField url=new JTextField();
 final JButton connect=new JButton("Conectar / renovar conta"),create=new JButton("Criar conta"),send=new JButton("Sincronizar catálogo"),disconnect=new JButton("Desconectar"),switchAccount=new JButton("Trocar conta"),close=new JButton("Fechar");
 final JCheckBox deletions=new JCheckBox("Propagar exclusões de livros físicos removidos localmente");
 final DefaultListModel<ObjectNode> conflictModel=new DefaultListModel<>();final JList<ObjectNode> conflictList=new JList<>(conflictModel);
 final JTextArea localText=new JTextArea(),remoteText=new JTextArea();final JButton keepLocal=new JButton("Manter local"),keepCloud=new JButton("Usar nuvem neste computador");
 final JComboBox<Biblioteca.Book> books=new JComboBox<>();final JTextArea shared=new JTextArea(),note=new JTextArea(4,40);final JButton addNote=new JButton("Adicionar à próxima sincronização");
 CloudDialog(JFrame owner,Biblioteca library,Runnable changed)throws Exception{
  super(owner,"Conta e sincronização · "+library.database.getFileName(),true);this.sync=new CloudSync(library);this.changed=changed;setSize(980,760);setMinimumSize(new Dimension(820,620));setLocationRelativeTo(owner);setDefaultCloseOperation(DO_NOTHING_ON_CLOSE);
  var root=new JPanel(new BorderLayout(0,18));root.setBackground(UiTheme.BACKGROUND);root.setBorder(BorderFactory.createEmptyBorder(22,24,18,24));setContentPane(root);
  var head=UiTheme.panel(new BorderLayout(0,8));head.add(UiTheme.eyebrow("CATÁLOGO CONECTADO"),BorderLayout.NORTH);head.add(account);var description=new JTextArea("Livros digitais permanecem neste computador. A sincronização envia e recebe todos os dados dos cadastros, capas e anotações.");description.setEditable(false);description.setOpaque(false);description.setLineWrap(true);description.setWrapStyleWord(true);description.setRows(2);description.setFont(description.getFont().deriveFont(12f));head.add(description,BorderLayout.SOUTH);root.add(head,BorderLayout.NORTH);
  var tabs=new JTabbedPane();root.add(tabs);var connection=UiTheme.panel(new BorderLayout(0,18));connection.setBorder(BorderFactory.createEmptyBorder(20,16,20,16));var actions=UiTheme.panel(new FlowLayout(FlowLayout.LEFT,8,0));actions.add(create);actions.add(connect);actions.add(disconnect);actions.add(switchAccount);connection.add(actions,BorderLayout.NORTH);
  var flow=UiTheme.panel(new BorderLayout(0,14));var status=UiTheme.panel(new BorderLayout(0,10));code.setFont(code.getFont().deriveFont(Font.BOLD,28));status.add(code,BorderLayout.NORTH);url.setEditable(false);url.setVisible(false);status.add(url);var hint=new JTextArea("1. Conecte sua conta pelo navegador e confirme o código.\n2. Confira a conta e o catálogo associados.\n3. Clique em Sincronizar catálogo quando quiser enviar e receber alterações.\n\nO primeiro envio inclui os registros ativos deste perfil. Nenhum arquivo PDF/EPUB, conteúdo de OCR, senha ou posição do leitor é enviado.");hint.setEditable(false);hint.setOpaque(false);hint.setLineWrap(true);hint.setWrapStyleWord(true);hint.setBorder(BorderFactory.createEmptyBorder(18,0,0,0));status.add(hint,BorderLayout.SOUTH);flow.add(status,BorderLayout.NORTH);var syncActions=UiTheme.panel(new BorderLayout(0,12));syncActions.add(deletions,BorderLayout.NORTH);UiTheme.primary(send);syncActions.add(send);flow.add(syncActions,BorderLayout.SOUTH);connection.add(flow);tabs.addTab("Conexão e sincronização",connection);
  var conflicts=UiTheme.panel(new BorderLayout(0,12));conflicts.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));conflictList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);conflictList.setVisibleRowCount(4);conflictList.setCellRenderer(new DefaultListCellRenderer(){public Component getListCellRendererComponent(JList<?> list,Object value,int i,boolean selected,boolean focus){super.getListCellRendererComponent(list,value,i,selected,focus);var n=(JsonNode)value;setText(n.path("local").path("book").path("title").asText("Exclusão local")+" · "+n.path("remote").path("book").path("title").asText());return this;}});conflicts.add(new JScrollPane(conflictList),BorderLayout.NORTH);var compare=new JPanel(new GridLayout(1,2,14,0));for(var entry:List.of(Map.entry("Seu cadastro local",localText),Map.entry("Versão da nuvem",remoteText))){var panel=UiTheme.panel(new BorderLayout(0,7));panel.add(new JLabel(entry.getKey()),BorderLayout.NORTH);entry.getValue().setEditable(false);entry.getValue().setLineWrap(true);entry.getValue().setWrapStyleWord(true);panel.add(new JScrollPane(entry.getValue()));compare.add(panel);}conflicts.add(compare);var resolve=UiTheme.panel(new FlowLayout(FlowLayout.RIGHT));resolve.add(keepLocal);resolve.add(keepCloud);conflicts.add(resolve,BorderLayout.SOUTH);tabs.addTab("Conflitos",conflicts);
  var comments=UiTheme.panel(new BorderLayout(0,12));comments.setBorder(BorderFactory.createEmptyBorder(16,16,16,16));for(var book:library.books())books.addItem(book);comments.add(books,BorderLayout.NORTH);shared.setEditable(false);shared.setLineWrap(true);shared.setWrapStyleWord(true);comments.add(new JScrollPane(shared));var compose=UiTheme.panel(new BorderLayout(0,7));note.setLineWrap(true);note.setWrapStyleWord(true);compose.add(new JLabel("Nova anotação compartilhada, assinada pela conta conectada"),BorderLayout.NORTH);compose.add(new JScrollPane(note));compose.add(addNote,BorderLayout.SOUTH);comments.add(compose,BorderLayout.SOUTH);tabs.addTab("Anotações compartilhadas",comments);
  var footer=UiTheme.panel(new BorderLayout(16,0));message.setFont(message.getFont().deriveFont(12f));footer.add(message);footer.add(close,BorderLayout.EAST);root.add(footer,BorderLayout.SOUTH);
  close.addActionListener(e->close());addWindowListener(new WindowAdapter(){public void windowClosing(WindowEvent e){close();}});
  create.addActionListener(e->{try{browse(URI.create(CloudSync.frontend()));}catch(Exception ex){failure(ex);}});
  connect.addActionListener(e->connect());send.addActionListener(e->{if(deletions.isSelected()&&JOptionPane.showConfirmDialog(this,"Confirmar exclusão na nuvem dos livros físicos removidos neste perfil? Arquivos no computador serão preservados.","Confirmar exclusões",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;runTask(()->{var result=sync.sync(deletions.isSelected(),this::progress);return "Enviados: "+result.uploaded()+" · Recebidos: "+result.downloaded()+" · Conflitos: "+result.conflicts();});});
  disconnect.addActionListener(e->{if(JOptionPane.showConfirmDialog(this,"Revogar a conexão deste perfil? Os cadastros locais e da nuvem serão mantidos.","Desconectar",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)runTask(()->{sync.disconnect(false);return "Dispositivo desconectado.";});});
  switchAccount.addActionListener(e->{if(JOptionPane.showConfirmDialog(this,"Uma nova associação não reutiliza o vínculo da conta anterior. Os dados locais deste perfil continuam disponíveis e poderão ser enviados para a nova conta ao sincronizar. Continuar?","Trocar conta",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)runTask(()->{sync.disconnect(true);return "Associação anterior removida. Use Conectar conta para escolher a nova conta.";});});
  conflictList.addListSelectionListener(e->{if(e.getValueIsAdjusting())return;var n=conflictList.getSelectedValue();localText.setText(n==null?"":describe(n.path("local")));remoteText.setText(n==null?"":describe(n.path("remote")));localText.setCaretPosition(0);remoteText.setCaretPosition(0);});
  keepLocal.addActionListener(e->resolve(true));keepCloud.addActionListener(e->resolve(false));books.addActionListener(e->loadComments());addNote.addActionListener(e->{var b=(Biblioteca.Book)books.getSelectedItem();if(b==null)return;try{sync.addComment(b.id,note.getText());note.setText("");message.setText("Anotação guardada para a próxima sincronização.");}catch(Exception ex){failure(ex);}});
  refresh();
 }
 static String describe(JsonNode item){if(item.path("deleted").asBoolean())return "Cadastro excluído nesta versão.";var book=item.path("book");var meta=book.path("metadata");return "Título: "+book.path("title").asText()+"\nAutor: "+meta.path("author").asText()+"\nISBN: "+meta.path("isbn").asText()+"\nEditora: "+meta.path("publisher").asText()+"\nCategoria: "+book.path("category").asText()+"\n\nResumo:\n"+book.path("summary").asText()+"\n\nAnotações:\n"+meta.path("notes").asText();}
 void browse(URI url)throws Exception{if(Boolean.getBoolean("catalogo.cloud.noBrowser"))return;if(!Desktop.isDesktopSupported()||!Desktop.getDesktop().isSupported(Desktop.Action.BROWSE)){this.url.setText(url.toString());this.url.setVisible(true);message.setText("Abra o endereço acima no navegador.");return;}Desktop.getDesktop().browse(url);}
 void connect(){setBusy(true);worker=new SwingWorker<CloudSync.ConnectionInfo,String>(){protected CloudSync.ConnectionInfo doInBackground()throws Exception{var pairing=sync.startPair();SwingUtilities.invokeLater(()->{if(!isDisplayable())return;code.setText("Código: "+pairing.code());url.setText(pairing.url().toString());url.setVisible(true);try{browse(pairing.url());}catch(Exception e){message.setText("Abra o endereço acima e confirme o código.");}});for(int i=0;i<120;i++){if(isCancelled())throw new InterruptedException();var info=sync.poll(pairing);if(info!=null)return info;Thread.sleep(5000);}throw new IllegalStateException("A conexão expirou. Tente novamente.");}protected void done(){if(!isDisplayable())return;try{get();message.setText("Conta conectada. Confira a conta e clique em Sincronizar catálogo.");code.setText(" ");url.setVisible(false);}catch(Exception e){failure(e);}finally{setBusy(false);try{refresh();}catch(Exception e){failure(e);}}}};worker.execute();}
 interface Task{String run()throws Exception;}
 void runTask(Task task){setBusy(true);worker=new SwingWorker<String,Void>(){protected String doInBackground()throws Exception{return task.run();}protected void done(){try{String text=get();if(isDisplayable())message.setText(text);}catch(Exception e){if(isDisplayable())failure(e);}finally{changed.run();if(isDisplayable()){setBusy(false);try{refresh();}catch(Exception e){failure(e);}}}}};worker.execute();}
 void progress(String text){SwingUtilities.invokeLater(()->{if(isDisplayable())message.setText(text);});}
 void setBusy(boolean value){for(var button:List.of(connect,create,disconnect,switchAccount,send,keepLocal,keepCloud,addNote))button.setEnabled(!value);deletions.setEnabled(!value);}
 void refresh()throws Exception{var info=sync.connection();account.setText(info==null?"Este perfil está sem uma conta conectada.":"Conta: "+info.email()+" · Banco: "+sync.lib.database.getFileName());boolean connected=info!=null;send.setEnabled(connected);disconnect.setEnabled(connected);switchAccount.setEnabled(connected);addNote.setEnabled(connected);var selected=conflictList.getSelectedValue();conflictModel.clear();for(var item:sync.conflicts())conflictModel.addElement(item);if(!conflictModel.isEmpty())conflictList.setSelectedIndex(0);keepLocal.setEnabled(!conflictModel.isEmpty());keepCloud.setEnabled(!conflictModel.isEmpty());loadComments();}
 void resolve(boolean local){var item=conflictList.getSelectedValue();if(item==null)return;String action=local?"Manter a edição local e enviá-la na próxima sincronização?":"Substituir este cadastro local pela versão da nuvem? Os arquivos serão preservados.";if(JOptionPane.showConfirmDialog(this,action,"Resolver conflito",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;runTask(()->{sync.resolve(item.path("local_id").asText(),local);return local?"Edição local preservada. Sincronize para enviá-la.":"Versão da nuvem aplicada.";});}
 void loadComments(){try{var b=(Biblioteca.Book)books.getSelectedItem();var text=new StringBuilder();if(b!=null)for(var item:sync.comments(b.id)){text.append(item.get("origin").equals("desktop")?"Importado do desktop · sincronizado por ":"").append(item.get("author")).append(" · ").append(item.get("created")).append("\n").append(item.get("body")).append("\n\n");}shared.setText(text.isEmpty()?"As anotações compartilhadas recebidas na sincronização aparecem aqui.":text.toString());shared.setCaretPosition(0);}catch(Exception e){failure(e);}}
 void failure(Exception error){Throwable cause=error;while(cause.getCause()!=null&&(cause instanceof java.util.concurrent.ExecutionException))cause=cause.getCause();message.setText(Objects.toString(cause.getMessage(),"Não foi possível concluir a operação."));message.setToolTipText(message.getText());}
 void close(){if(worker!=null&&!worker.isDone())worker.cancel(true);dispose();}
}
